import { POPULAR_BUILDINGS } from '../buildingDefs';
import { extractStreet } from './streets';
import { hashSeed, mulberry32, offsetPoint, type LatLng } from './geometry';
import { hasDistrict, inWater, pointAllowed, randomAllowedPoint, wardAt, wardKey } from './areas';
import COORDS from './coords.json';

export const PRECISION = { building: 0, street: 1, ward: 2, district: 3, nearBuilding: 4 } as const;
export type Precision = 0 | 1 | 2 | 3 | 4;

/** Generated by scripts/build-geo-coords.ts. Ward keys are "<District>|<normalized ward>",
 *  street keys "<District>|<street key>", building keys the BuildingDef name. */
export interface GeoCoords {
  buildings: Record<string, LatLng>;
  wards: Record<string, LatLng>;
  streets: Record<string, LatLng>;
  /** Names the geocoder tried and could not place — skipped on re-runs. */
  misses: string[];
}

/** `geoArea` is the ward key the pin is confined to ('' = just its district), so the
 *  map's overlap nudging (client side) keeps it there too. */
export interface Placement { geo: [number, number, Precision]; geoLabel: string; geoArea: string }

// How far listings sharing one anchor are spread, so their pins don't sit on
// top of each other. Scaled to how big the anchor really is.
const SPREAD_M = { building: 30, nearBuilding: 300, street: 150, ward: 350, district: 500 };

// Places pinned by verified address (Blake, 2026-09-26): map-only, so unlike
// POPULAR_BUILDINGS they don't create a building page or a "Popular buildings" card.
// spreadM is roughly the grounds' size. `near: true` = a landmark people live NEAR,
// never in (parks, malls, resorts): always labelled "Near …".
// Coordinates are OpenStreetMap features whose name/address matched — don't add a
// place without that check: fuzzy geocoding put "Sam Towers" on Meridian Towers.
// `address`: the street address to SHOW (building records); only set from an address Blake gave.
